// Builds the Brand DNA prompt from the form data + whatever we could read from the website.
// Input: either the webhook item (no website) or the "Fetch Website" result (text in `data`).
const body = $('Webhook: Analyse Brand').first().json.body || {};
const brandName = String(body.brandName || '').trim();
if (!brandName) {
  return [{ json: { statusCode: 400, body: { error: 'brandName is required' } } }];
}

const html = typeof $json.data === 'string' ? $json.data : '';
const fetchError = $json.error ? ($json.error.message || 'could not fetch website') : null;

function extractSite(src) {
  if (!src) return null;
  const pick = (re) => { const m = src.match(re); return m ? m[1].trim() : ''; };
  const title = pick(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const description =
    pick(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i) ||
    pick(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']*)["']/i);
  const themeColor = pick(/<meta[^>]+name=["']theme-color["'][^>]*content=["']([^"']*)["']/i);

  // Most-used hex colours in inline CSS / markup
  const counts = {};
  for (const m of src.matchAll(/#(?:[0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b/g)) {
    let h = m[0].toLowerCase();
    if (h.length === 4) h = '#' + h.slice(1).split('').map((c) => c + c).join('');
    counts[h] = (counts[h] || 0) + 1;
  }
  const colors = Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 12)
    .map(([h, n]) => `${h} (used ${n}x)`);

  // Font families from CSS and Google Fonts links
  const fonts = new Set();
  for (const m of src.matchAll(/font-family\s*:\s*([^;}"']+)/gi)) {
    fonts.add(m[1].split(',')[0].trim().replace(/["']/g, ''));
  }
  for (const m of src.matchAll(/fonts\.googleapis\.com\/css2?\?family=([^"'&]+)/gi)) {
    let fam = m[1];
    try { fam = decodeURIComponent(fam); } catch (e) {}
    fam.split('|').forEach((f) => fonts.add(f.split(':')[0].replace(/\+/g, ' ')));
  }

  const text = src
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);

  return {
    title,
    description,
    themeColor,
    colors,
    fonts: [...fonts].filter((f) => f && !/^(inherit|initial|var\()/i.test(f)).slice(0, 8),
    text,
  };
}

const site = extractSite(html);

const system = `You are a senior brand strategist AI. Synthesise all provided source signals into a Brand DNA profile.
Return ONLY a JSON object with exactly this shape:
{
  "brandName": string,
  "colors": { "primary": hex_string, "secondary": hex_string, "accent": hex_string, "neutral": hex_string },
  "typography_feel": string,
  "visual_style": string,
  "vibe": [string, string, string, string],
  "products_services": [string, string, string, string],
  "target_audience": string,
  "communication_tone": string,
  "content_themes": [string, string, string, string],
  "hashtag_clusters": [string, string, string, string, string, string],
  "do": [string, string, string],
  "dont": [string, string, string],
  "one_liner": string
}
Priority of evidence: PDF visual insights > colours/fonts extracted from the website > website copy > your assumptions.
Hex colours must form a coherent, aesthetically strong palette. Be concrete and specific, never generic.`;

let user = `Brand name: ${brandName}
Website: ${body.websiteUrl || 'not provided'}
Instagram: ${body.igHandle ? '@' + String(body.igHandle).replace(/^@/, '') : 'not provided'}
PDF catalogue provided: ${body.pdfInsights ? 'yes' : 'no'}
`;

if (site) {
  user += `
WEBSITE EXTRACTION (read directly from the site's HTML):
- Page title: ${site.title || 'n/a'}
- Meta description: ${site.description || 'n/a'}
- Theme colour: ${site.themeColor || 'n/a'}
- Most-used colours: ${site.colors.join(', ') || 'none found'}
- Fonts: ${site.fonts.join(', ') || 'none found'}
- Visible copy (truncated): ${site.text || 'n/a'}
`;
} else if (body.websiteUrl) {
  user += `\nWebsite could not be read (${fetchError || 'empty response'}). Infer from the URL and other sources.\n`;
}

if (body.pdfInsights) {
  user += `\nPDF VISUAL ANALYSIS (HIGH PRIORITY - extracted from catalogue pages):\n${JSON.stringify(body.pdfInsights, null, 2)}\n`;
}

user += `\nBuild a detailed, specific Brand DNA. Colours must reflect the actual brand aesthetic. Avoid vague adjectives.`;

return [{
  json: {
    route: 'analyse-brand',
    resultKey: 'dna',
    request: { system, parts: [{ text: user }] },
  },
}];

// Builds a vision request from rasterised PDF pages (base64 JPEGs sent by Brandly).
const body = $('Webhook: Analyse PDF').first().json.body || {};
const pages = Array.isArray(body.pages)
  ? body.pages.filter((p) => typeof p === 'string' && p.length > 0)
  : [];

if (pages.length === 0) {
  return [{ json: { statusCode: 400, body: { error: 'No pages provided' } } }];
}

const system = `You analyse rasterised pages from a brand PDF catalogue.
Each page is rendered at full resolution - raster photos, vector illustrations, layered design elements,
typography, colour blocks, gradients and layout are all visible. Analyse everything across all pages.
Return ONLY a JSON object with exactly this shape:
{
  "pdf_colors": ["#hex1", "#hex2", "#hex3", "#hex4", "#hex5"],
  "pdf_visual_style": string,
  "pdf_design_aesthetic": string,
  "pdf_vibe": [string, string, string, string],
  "pdf_products_services": [string, string, string, string],
  "pdf_typography_feel": string,
  "pdf_layout_patterns": string,
  "pdf_brand_motifs": string,
  "pdf_target_audience": string,
  "pdf_communication_tone": string,
  "pdf_content_themes": [string, string, string, string]
}`;

// Cap at 8 pages to keep cost reasonable (same as the original Brandly route)
const parts = pages.slice(0, 8).map((p) => ({
  inline_data: {
    mime_type: 'image/jpeg',
    data: p.replace(/^data:image\/[a-z]+;base64,/i, ''),
  },
}));
parts.push({ text: `Brand name: ${body.brandName || 'unknown'}. Analyse these catalogue pages.` });

return [{
  json: {
    route: 'analyse-pdf',
    resultKey: 'insights',
    request: { system, parts },
  },
}];

// Builds the "full post package" prompt (port of Brandly's /api/generate-post).
const body = $('Webhook: Generate Post').first().json.body || {};

const TEMPLATES = {
  product_launch: ['Product Launch', 'Focus on the key benefit, create urgency, include a strong CTA'],
  announcement: ['Announcement', 'Conversational, celebratory tone - make followers feel part of the journey'],
  engagement: ['Engagement', 'Ask one clear question, make it easy and fun to answer'],
  educational: ['Educational', 'Use 3-5 clear tips or steps, establish expertise without being dry'],
  behind_scenes: ['Behind the Scenes', 'Personal, authentic, humanise the brand - show process not perfection'],
  testimonial: ['Testimonial', 'Lead with the result, make it relatable, include social proof elements'],
  seasonal: ['Seasonal / Trending', 'Connect the trend to the brand naturally - avoid forced relevance'],
  ugc: ['UGC / Repost', 'Grateful, community-focused tone - give credit and invite more'],
};
const LIMITS = { instagram: 2200, facebook: 63206, linkedin: 3000, twitter: 280 };

if (!body.brandDNA) {
  return [{ json: { statusCode: 400, body: { error: 'brandDNA is required' } } }];
}
const platforms = (Array.isArray(body.platforms) && body.platforms.length ? body.platforms : ['instagram'])
  .filter((p) => LIMITS[p]);
const [label, hint] = TEMPLATES[body.template] || ['General', 'On-brand, engaging social post'];

const system = `You are an expert social media content strategist.
You write deeply on-brand content that feels human, not AI-generated.
Return ONLY a JSON object.`;

const user = `Brand DNA:
${JSON.stringify(body.brandDNA, null, 2)}

Content request:
- Template: ${label} - ${hint}
- Topic/focus: ${body.topic || 'general brand content'}
- Platforms: ${platforms.join(', ')}
- Character limits: ${platforms.map((p) => `${p}: ${LIMITS[p]} chars`).join(', ')}
- Tone override: ${body.tone || 'match brand tone'}
- Additional context: ${body.additionalContext || 'none'}

Return this JSON shape:
{
  "caption": string (primary caption, optimised for Instagram, within 2200 chars),
  "hashtags": string[] (8-15 hashtags, mix of broad and niche, each including the # symbol),
  "imagePrompt": string (detailed image-generation prompt matching the brand visual style, 2-3 sentences),
  "cta": string (clear call to action, 1 sentence),
  "bestTimeToPost": string (e.g. "Tuesday-Thursday, 7-9am or 6-8pm"),
  "postType": string (e.g. "Carousel", "Single image", "Reel", "Story"),
  "platformVariants": {
    "instagram": string (caption adapted for Instagram),
    "facebook": string (longer, more conversational, no hashtags needed),
    "linkedin": string (professional tone, insight-driven, 3 hashtags max),
    "twitter": string (punchy, under 280 chars including hashtags)
  }
}

Rules:
- platformVariants must only include the requested platforms: ${platforms.join(', ')}
- Write captions that sound like a real human, not AI
- Embed the brand's communication tone and vibe naturally`;

return [{
  json: {
    route: 'generate-post',
    resultKey: 'post',
    request: { system, parts: [{ text: user }] },
  },
}];

// Builds the automation prompt. Input comes from "Read RSS Feed", "Fetch Product Page",
// or straight from the Switch (recurring / unknown trigger).
const body = $('Webhook: Automation').first().json.body || {};
if (!body.brandDNA) {
  return [{ json: { statusCode: 400, body: { error: 'brandDNA is required' } } }];
}

const cfg = body.triggerConfig || { type: body.triggerType };
const platforms = Array.isArray(body.platforms) && body.platforms.length ? body.platforms : ['instagram'];
const items = $input.all().map((i) => i.json);
let context = '';

if (cfg.type === 'rss') {
  const articles = items.filter((j) => j && j.title);
  if (articles.length) {
    const a = articles[0]; // newest item
    const snippet = String(a.contentSnippet || a.content || a.summary || '').slice(0, 1500);
    context = `Latest RSS article from ${cfg.feedUrl}:\nTitle: ${a.title}\nLink: ${a.link || ''}\nPublished: ${a.isoDate || a.pubDate || ''}\nSnippet: ${snippet}`;
  } else {
    context = `No articles could be read from RSS feed: ${cfg.feedUrl}`;
  }
} else if (cfg.type === 'product_update') {
  const html = items[0] && typeof items[0].data === 'string' ? items[0].data : '';
  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 3000);
  context = text
    ? `Product page content from ${cfg.sourceUrl}:\n${text}`
    : `Could not read product page: ${cfg.sourceUrl}`;
} else if (cfg.type === 'recurring') {
  context = `Recurring post - topic: ${cfg.topic || 'general brand content'}`;
} else {
  context = body.triggerContext || 'No specific context provided.';
}

const system = `You are an automated social media content generator.
Generate content based on the provided trigger context and brand DNA.
Return ONLY a JSON object.`;

const user = `Brand DNA:
${JSON.stringify(body.brandDNA, null, 2)}

Automation trigger:
- Type: ${cfg.type || 'unknown'}
- Context: ${context}
- Target platforms: ${platforms.join(', ')}

Auto-generate a post and return:
{
  "caption": string,
  "hashtags": string[] (each including the # symbol),
  "imagePrompt": string,
  "cta": string,
  "bestTimeToPost": string,
  "postType": string,
  "platformVariants": { one entry per target platform: ${platforms.join(', ')} }
}`;

return [{
  json: {
    route: 'automation',
    resultKey: 'post',
    request: { system, parts: [{ text: user }] },
  },
}];

// Turns the Gemini response into the JSON shape Brandly expects: { dna } / { insights } / { post }.
const BUILD_NODES = [
  'Build: Brand Prompt',
  'Build: PDF Prompt',
  'Build: Post Prompt',
  'Build: Automation Prompt',
];

let meta = null;
for (const name of BUILD_NODES) {
  try {
    if ($(name).isExecuted) { meta = $(name).first().json; break; }
  } catch (e) { /* node not part of this run */ }
}
if (!meta) {
  return [{ json: { statusCode: 500, body: { error: 'Could not determine which request this was' } } }];
}

const res = $input.first().json;
const candidate = (res.candidates || [])[0];

if (!candidate) {
  const reason = (res.promptFeedback && res.promptFeedback.blockReason) || 'no candidates returned';
  return [{ json: { statusCode: 502, body: { error: `AI returned no result (${reason})` } } }];
}

const text = ((candidate.content && candidate.content.parts) || [])
  .filter((p) => typeof p.text === 'string' && !p.thought)
  .map((p) => p.text)
  .join('');

function parseJson(raw) {
  const clean = String(raw).replace(/```json|```/g, '').trim();
  try { return JSON.parse(clean); } catch (e) {}
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { return JSON.parse(clean.slice(start, end + 1)); } catch (e) {}
  }
  return null;
}

const parsed = parseJson(text);
if (!parsed || typeof parsed !== 'object') {
  const finish = candidate.finishReason ? ` (finishReason: ${candidate.finishReason})` : '';
  return [{ json: { statusCode: 502, body: { error: `Failed to parse AI response${finish}` } } }];
}

return [{ json: { statusCode: 200, body: { [meta.resultKey]: parsed } } }];

// Runs when the Gemini HTTP call itself fails (bad key, quota, timeout, ...).
const err = $json.error || {};
let detail = err.message || 'unknown error';
if (err.description) detail += ` - ${err.description}`;
return [{ json: { statusCode: 502, body: { error: `AI request failed: ${detail}` } } }];

// Builds the image requests: Pollinations (primary) and Alibaba Qwen-Image (backup).
// Body: { prompt: string, aspect?: "1:1"|"4:5"|"4:3"|"16:9"|"9:16", brandDNA?: BrandDNA, negativePrompt?: string }
const POLLINATIONS_MODEL = 'tongyi-mai/z-image-turbo'; // cheap + good; also black-forest-labs/flux.1-schnell (cheapest)
const ALIBABA_MODEL = 'qwen-image-3.0';                 // also qwen-image-3.0-pro, qwen-image-2.1-turbo

const body = $('Webhook: Generate Image').first().json.body || {};
const prompt = String(body.prompt || '').trim();
if (!prompt) {
  return [{ json: { statusCode: 400, body: { error: 'prompt is required' } } }];
}

const SIZES = {
  //        Pollinations (WxH)   Alibaba (W*H, 512^2..2048^2)
  '1:1':  ['1024x1024', '1328*1328'],
  '4:5':  ['1024x1280', '1104*1380'],
  '4:3':  ['1152x864',  '1472*1104'],
  '16:9': ['1344x768',  '1664*928'],
  '9:16': ['768x1344',  '928*1664'],
};
const aspect = SIZES[body.aspect] ? body.aspect : '1:1';

// Add the brand's art direction so every image matches the Brand DNA
let direction = '';
const dna = body.brandDNA;
if (dna) {
  const c = dna.colors || {};
  direction =
    ` Brand art direction: ${dna.visual_style || 'on-brand'}.` +
    ` Colour palette: ${[c.primary, c.secondary, c.accent, c.neutral].filter(Boolean).join(', ')}.` +
    (Array.isArray(dna.vibe) && dna.vibe.length ? ` Mood: ${dna.vibe.join(', ')}.` : '');
}
const suffix = ' Do not add text, logos or watermarks unless the prompt asks for them.';

// Keep the whole prompt within 800 characters (Alibaba's limit), trimming the scene description first
const room = 800 - direction.length - suffix.length;
const text = (prompt.length > room ? prompt.slice(0, Math.max(room - 3, 0)) + '...' : prompt) + direction + suffix;
const negative = body.negativePrompt || 'blurry, low quality, distorted, deformed, watermark, garbled text';

return [{
  json: {
    route: 'generate-image',
    aspect,
    request: {
      pollinations: {
        model: POLLINATIONS_MODEL,
        prompt: text,
        size: SIZES[aspect][0],
        n: 1,
        response_format: 'url',
      },
      alibaba: {
        model: ALIBABA_MODEL,
        input: { messages: [{ role: 'user', content: [{ text }] }] },
        parameters: { size: SIZES[aspect][1], n: 1, watermark: false, prompt_extend: true, negative_prompt: negative },
      },
    },
  },
}];

// Reads the image URL from either provider's response.
//  - Pollinations (OpenAI format): data[0].url  -> permanent link on media.pollinations.ai
//  - Alibaba Qwen-Image:           output.choices[0].message.content[].image -> expires after 24 hours
const meta = $('Build: Image Request').first().json;
const res = $json;

let imageUrl = null;
let provider = null;
let model = null;
let expiresAt = null;

if (Array.isArray(res.data) && res.data[0] && res.data[0].url) {
  imageUrl = res.data[0].url;
  provider = 'pollinations';
  model = meta.request.pollinations.model;
} else {
  const content = (res.output && res.output.choices && res.output.choices[0] &&
    res.output.choices[0].message && res.output.choices[0].message.content) || [];
  const hit = content.find((c) => c && c.image);
  if (hit) {
    imageUrl = hit.image;
    provider = 'alibaba';
    model = meta.request.alibaba.model;
    expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
  }
}

if (!imageUrl) {
  const reason = res.message || res.code || (res.error && res.error.message) || 'no image returned';
  return [{ json: { statusCode: 502, body: { error: `Image generation failed: ${reason}` } } }];
}

return [{ json: { statusCode: 200, body: { imageUrl, provider, model, aspect: meta.aspect, expiresAt } } }];

// Runs when both Pollinations (primary) and Alibaba (backup) failed.
function describe(err) {
  if (!err) return null;
  const raw = `${err.message || ''} ${err.description || ''}`;
  if (/Unpurchased/i.test(raw)) return 'Alibaba account not activated for this model (activate Model Studio in the Alibaba Cloud console)';
  if (/InvalidApiKey/i.test(raw)) return 'Alibaba API key rejected';
  if (/\b402\b|insufficient|balance|pollen/i.test(raw)) return 'Pollinations balance is used up (add pollen at enter.pollinations.ai)';
  if (/\b401\b|unauthori[sz]ed/i.test(raw)) return 'Pollinations API key rejected';
  if (/\b429\b|rate/i.test(raw)) return 'Pollinations rate limit hit - wait a moment and try again';
  return `${err.message || 'unknown error'}${err.description ? ' - ' + err.description : ''}`;
}

let primary = null;
try {
  if ($('Pollinations: Generate Image').isExecuted) primary = $('Pollinations: Generate Image').first().json.error;
} catch (e) {}
const backup = $json.error;

const parts = [];
if (primary) parts.push(`Pollinations: ${describe(primary)}`);
if (backup) parts.push(`Alibaba backup: ${describe(backup)}`);

return [{ json: { statusCode: 502, body: { error: `Image generation failed. ${parts.join('. ') || 'Unknown error'}.` } } }];

// Turns a Brandly ScheduledPost into one Ayrshare request per platform.
// Body: { post: ScheduledPost, platforms?: string[], mediaUrls?: string[], publishAt?: ISO, profileKey?: string }
const body = $('Webhook: Publish').first().json.body || {};
const post = body.post || {};
const content = post.content || {};
const platforms = (body.platforms || post.platforms || []).filter(Boolean);

const AYRSHARE_NAME = { instagram: 'instagram', facebook: 'facebook', linkedin: 'linkedin', twitter: 'twitter' };
const mediaUrls = (body.mediaUrls || (post.mediaUrl ? [post.mediaUrl] : []))
  .filter((u) => typeof u === 'string' && /^https?:\/\//i.test(u));

let scheduleDate = null;
if (body.publishAt) {
  const d = new Date(body.publishAt);
  if (!isNaN(d.getTime()) && d.getTime() > Date.now() + 60 * 1000) scheduleDate = d.toISOString();
}

const headers = { 'Content-Type': 'application/json' };
if (body.profileKey) headers['Profile-Key'] = String(body.profileKey);

const hashtags = Array.isArray(content.hashtags) ? content.hashtags.join(' ') : '';
const jobs = [];
const invalid = [];

if (!platforms.length) invalid.push({ platform: 'all', ok: false, error: 'No platforms selected' });

for (const p of platforms) {
  const name = AYRSHARE_NAME[p];
  if (!name) { invalid.push({ platform: p, ok: false, error: 'Unsupported platform' }); continue; }

  const variants = content.platformVariants || {};
  let text = variants[p] || [content.caption, hashtags].filter(Boolean).join('\n\n');
  if (!text) { invalid.push({ platform: p, ok: false, error: 'Post has no text' }); continue; }
  if (p === 'twitter' && text.length > 280) text = text.slice(0, 277) + '...';
  if (p === 'instagram' && mediaUrls.length === 0) {
    invalid.push({ platform: p, ok: false, error: 'Instagram needs an image or video URL (mediaUrl)' });
    continue;
  }

  const payload = { post: text, platforms: [name] };
  if (mediaUrls.length) payload.mediaUrls = mediaUrls;
  if (scheduleDate) payload.scheduleDate = scheduleDate;
  jobs.push({ platform: p, headers, payload });
}

return [{ json: { postId: post.id || null, scheduleDate, jobs, invalid } }];

// Combines Ayrshare results (one item per platform) with platforms rejected up front.
const build = $('Build: Publish Requests').first().json;
const results = [...build.invalid];

let responses = [];
try {
  if ($('Ayrshare: Publish').isExecuted) responses = $('Ayrshare: Publish').all().map((i) => i.json);
} catch (e) { /* nothing was sent */ }

responses.forEach((r, i) => {
  const job = build.jobs[i] || {};
  if (r.error) {
    const msg = r.error.message || 'request failed';
    results.push({ platform: job.platform, ok: false, error: r.error.description ? `${msg} - ${r.error.description}` : msg });
    return;
  }
  const ok = r.status === 'success' || r.status === 'scheduled';
  const first = (r.postIds || [])[0] || {};
  const errText = (r.errors || []).map((e) => e.message || JSON.stringify(e)).join('; ');
  results.push({
    platform: job.platform,
    ok,
    id: r.id || first.id || null,
    postUrl: first.postUrl || null,
    error: ok ? undefined : (errText || r.message || 'Ayrshare rejected the post'),
  });
});

const okCount = results.filter((r) => r.ok).length;
const status = okCount === 0 ? 'failed' : okCount === results.length ? (build.scheduleDate ? 'scheduled' : 'published') : 'partial';

return [{
  json: {
    statusCode: okCount === 0 ? 502 : 200,
    body: { postId: build.postId, status, scheduledFor: build.scheduleDate, results },
  },
}];
